    /// Title 1: 28/600, line AUTO.
    static let title1 = TaleedTextStyle(
        size: 28, weight: .semibold, lineHeight: nil, letterSpacing: 0,
        relativeTo: .title
    )
    /// Title 2: 22/600, line AUTO.
    static let title2 = TaleedTextStyle(
        size: 22, weight: .semibold, lineHeight: nil, letterSpacing: 0,
        relativeTo: .title2
    )
    /// Headline: 18/600, line AUTO.
    static let headline = TaleedTextStyle(
        size: 18, weight: .semibold, lineHeight: nil, letterSpacing: 0,
        relativeTo: .body
    )
